# Helper functions for Gaussian elimination and matrix operations
def gaussian_elimination(matrix):
    n = len(matrix)
    for i in range(n):
        # Find pivot row
        max_row = i
        for j in range(i+1, n):
            if abs(matrix[j][i]) > abs(matrix[max_row][i]):
                max_row = j
        # Swap rows
        matrix[i], matrix[max_row] = matrix[max_row], matrix[i]

        # Eliminate lower entries
        pivot = matrix[i][i]
        for j in range(i, n):
            matrix[i][j] /= pivot
        for k in range(i+1, n):
            factor = matrix[k][i]
            for j in range(i, n):
                matrix[k][j] -= factor * matrix[i][j]

def rank(matrix):
    n = len(matrix)
    augmented_matrix = [row[:] + [0] * (n - len(row)) for row in matrix]
    gaussian_elimination(augmented_matrix)
    rank = 0
    for row in augmented_matrix:
        if any(x != 0 for x in row):
            rank += 1
    return rank

def quasi_plurality_matrix(cnf):
    n = len(cnf[0])
    matrix = [[0] * (2*n) for _ in range(2*n)]

    for clause in cnf:
        literals = set()
        for literal in clause:
            if literal > 0:
                literals.add(literal)
            else:
                literals.add(-literal)

        for lit1 in literals:
            for lit2 in literals:
                matrix[lit1-1][lit2-1] += 1

    return matrix

